package br.com.equilibra.transaction.api;
import br.com.equilibra.transaction.application.TransferService; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.support.ServletUriComponentsBuilder; import java.net.URI;
@RestController @RequestMapping("/transfers") @Tag(name="Transfers",description="Transferências entre contas do usuário autenticado") @SecurityRequirement(name="bearerAuth") public class TransferController{private final TransferService service;public TransferController(TransferService service){this.service=service;}@PostMapping public ResponseEntity<TransferResponse> create(@Valid @RequestBody CreateTransferRequest r){TransferResponse x=service.create(r);URI l=ServletUriComponentsBuilder.fromCurrentRequest().path("/{id}").buildAndExpand(x.id()).toUri();return ResponseEntity.created(l).body(x);}@GetMapping public ResponseEntity<TransferPageResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="false")boolean includeCancelled){return ResponseEntity.ok(service.list(page,size,includeCancelled));}@GetMapping("/{id}")public ResponseEntity<TransferResponse> get(@PathVariable String id){return ResponseEntity.ok(service.get(id));}@PutMapping("/{id}")public ResponseEntity<TransferResponse> update(@PathVariable String id,@Valid @RequestBody UpdateTransferRequest r){return ResponseEntity.ok(service.update(id,r));}@PatchMapping("/{id}/cancel")public ResponseEntity<TransferResponse> cancel(@PathVariable String id){return ResponseEntity.ok(service.cancel(id));}}
